  auto dynamicsFile=folder.getChildFile("manual-dynamics.wav");tonescope::writeWav(dynamicsFile.getFullPathName().toStdString(),dynamics);
  Context compression;compression.sessionId=bridge->sessionId();compression.requestId=juce::Uuid().toDashedString();compression.sourceFile=dynamicsFile;compression.sourceHash=fileHash(dynamicsFile);compression.first=0;compression.last=192000;compression.revision=20;compression.parameters.compressor=true;compression.parameters.thresholdDb=0;compression.parameters.kneeDb=0;compression.parameters.releaseMs=100;compression.graphHash=tonescope::session::hashParameters(compression.parameters);compression.rawWet=std::make_shared<tonescope::AudioData>(tonescope::render(dynamics,compression.parameters));compression.descriptors=tonescope::session::parameterDescriptors(compression.parameters,48000);compression.passages=object({{"origin","manual"},{"soft",juce::Array<juce::var>{24000,72000}},{"hard",juce::Array<juce::var>{120000,168000}}});
